<script setup lang="ts">
const props=withDefaults(defineProps<{width?:number;height?:number;bottomColor?:string;miniProgram?:boolean}>(),{width:390,bottomColor:'#f5f7fb'})
const host=shallowRef<HTMLElement|null>(null),size=ref({width:0,height:0}),measured=ref(false)
const naturalWidth=computed(()=>props.width+16),naturalHeight=computed(()=>(props.height??Math.round(props.width*844/390))+16),scale=computed(()=>Math.max(0,Math.min(1,(size.value.width-12)/naturalWidth.value,(size.value.height-12)/naturalHeight.value)))
